import React from 'react';
import { onKeyEnter } from './utils';

describe('onKeyEnter', () => {
  it('should call the function if the event key is Enter', () => {
    const callbackMock = jest.fn();
    const eventMock = { key: 'Enter' } as React.KeyboardEvent<HTMLLIElement>;
    onKeyEnter(eventMock, () => callbackMock());
    expect(callbackMock).toHaveBeenCalled();
  });

  it('should not call the function if the event key is not Enter', () => {
    const callbackMock = jest.fn();
    const eventMock = {} as React.KeyboardEvent<HTMLLIElement>;
    onKeyEnter(eventMock, () => callbackMock());
    expect(callbackMock).not.toHaveBeenCalled();
  });
});
